t.script:
$(document).on('signature_submitted', function (ev, data) {
    if (data &
     data.success) {
        // Fetch the updated signature image (assuming it’s now stored)
        $.get(window.location.href, function (html) {
            const newContent = $(html).find('#accountant_content').html();
            $('#accountant_content').html(newContent);
        });
    }
});
